# Pseudocode for a metaclass that decorates all methods
class AutoLog(type):
    def __new__(mcls, name, bases, dct):
        def log_wrapper(func):
            def inner(*args, **kw):
                print(f'Calling {func.__name__}')
                return func(*args, **kw)
            return inner
        for attr, val in dct.items():
            if callable(val):
                dct[attr] = log_wrapper(val)
        return super().__new__(mcls, name, bases, dct)

class Service(metaclass=AutoLog):
    def start(self):
        print('started')
    def stop(self):
        print('stopped')

svc = Service()
svc.start()
svc.stop()

