registry = {}

class RegisterMeta(type):
    def __new__(mcls, name, bases, dct):
        cls = super().__new__(mcls, name, bases, dct)
        registry[name] = cls
        return cls

class Base(metaclass=RegisterMeta):
    pass

class Foo(Base):
    pass

class Bar(Base):
    pass

print(registry)  # {'Base': <class '__main__.Base'>, 'Foo': <class '__main__.Foo'>, 'Bar': <class '__main__.Bar'>}
# Each time a new subclass is defined, RegisterMeta inserts it into the registry, enabling factory patterns or plugin discovery without manual bookkeeping.
